/* Pure, deterministic career planning and reporting. No external services. */
(function(root){
 const day=d=>d.toISOString().slice(0,10);
 const shift=(d,n)=>{const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+n);return day(x)};
 const phases=[['prepare','Preparation','Define the release and confirm credits',-42,90],['produce','Production','Finish and review the recording',-28,180],['deliver','Delivery','Prepare artwork, metadata and delivery',-14,90],['promote','Promotion','Run your release promotion plan',-7,120],['review','Review','Review results and choose your next step',14,45]];
 function migrate(input){const s=JSON.parse(JSON.stringify(input));s.version=3;s.events=s.events||[];s.careerActivities=s.careerActivities||[];s.observations=s.observations||[];s.revisions=s.revisions||[];s.tasks=(s.tasks||[]).map(t=>({...t,releaseId:t.releaseId||null,dependencies:t.dependencies||[],effort:t.effort||t.minutes||30,dateMode:t.dateMode||(t.due?'manual':'auto'),suggestedDate:t.suggestedDate||'',order:t.order??0}));s.releases=(s.releases||[]).map(r=>({...r,goal:r.goal||'',milestones:r.milestones||[]}));return s;}
 function seed(s,r){let prev=null;for(const [phase,domain,title,offset,effort] of phases){const id=r.id+':'+phase; if(!s.tasks.some(t=>t.id===id))s.tasks.push({id,releaseId:r.id,phase,domain,title,reason:'Supports '+r.title+' through '+domain.toLowerCase()+'.',steps:phase==='prepare'?'Define your outcome, review your foundations, and confirm collaborator credits.':phase==='produce'?'Finish the creative work and review the recording against your release goal.':phase==='deliver'?'Check artwork, credits, metadata and your distributor’s delivery requirements.':phase==='promote'?'Prepare your message and choose audience activities that fit your resources.':'Record what happened, what you learned, and one next action.',status:'To do',notes:'',due:'',suggestedDate:'',dateMode:'auto',effort,offset,dependencies:prev?[prev]:[],generated:true,archived:false,order:0});prev=id;}}
 function blocked(s,t){return (t.dependencies||[]).some(id=>{const p=s.tasks.find(x=>x.id===id);return p&&p.status!=='Done'});}
 function schedule(s,today){const capacity={'1–3 hours':60,'4–7 hours':240,'8–15 hours':480,'16+ hours':960}[s.profile.hours]||180;const warnings=[];const buckets={};const dates={};const updates=[];let candidates=s.tasks.filter(t=>!t.archived&&t.status!=='Done'&&t.status!=='Deferred').sort((a,b)=>{const ra=s.releases.find(r=>r.id===a.releaseId),rb=s.releases.find(r=>r.id===b.releaseId);return (ra?.date||'9999').localeCompare(rb?.date||'9999')||(a.offset||0)-(b.offset||0)||a.id.localeCompare(b.id)});const ordered=[],visited=new Set(),visiting=new Set();function visit(t){if(visited.has(t.id))return;if(visiting.has(t.id)){warnings.push('A task dependency cycle needs review.');return;}visiting.add(t.id);for(const id of t.dependencies||[]){const dep=candidates.find(x=>x.id===id);if(dep)visit(dep);}visiting.delete(t.id);visited.add(t.id);ordered.push(t);}candidates.forEach(visit);candidates=ordered;const week=d=>Math.floor((new Date(d+'T12:00:00Z')-new Date(today+'T12:00:00Z'))/604800000);for(const t of candidates){if(t.dateMode==='manual'&&t.due&&s.releases.find(r=>r.id===t.releaseId)?.status!=='Archived'){dates[t.id]=t.due;buckets[week(t.due)]=(buckets[week(t.due)]||0)+(Number(t.effort)||30);}}let order=0;
 for(const t of candidates){const r=s.releases.find(r=>r.id===t.releaseId);if(r?.status==='Archived')continue;let target=r?.date?shift(r.date,t.offset||0):today;target=target<today?today:target;for(const dep of t.dependencies||[]){const p=s.tasks.find(x=>x.id===dep);if(p&&p.status!=='Done'){const dependencyDate=dates[dep]||p.due||p.suggestedDate;if(dependencyDate&&target<=dependencyDate)target=shift(dependencyDate,1);}}
 const effort=Number(t.effort)||30;
 if(effort>capacity)warnings.push(t.title+': estimated effort exceeds your weekly availability.');
 if(t.dateMode==='manual'&&t.due){if(t.due<target)warnings.push(t.title+': your chosen date conflicts with preparation or dependency timing.');target=t.due;}else{let loops=0;while((buckets[week(target)]||0)+Math.min(effort,capacity)>capacity&&loops++<520)target=shift(target,7);}
 if(t.dateMode!=='manual'||!t.due)buckets[week(target)]=(buckets[week(target)]||0)+effort;if(buckets[week(target)]>capacity)warnings.push('Work scheduled around '+target+' exceeds your weekly availability.');dates[t.id]=target;
 if(r?.date&&t.phase!=='review'&&target>r.date)warnings.push(r.title+': '+t.title+' falls after the release date. Change the date or reduce the work.');
 const next={suggestedDate:target,order:order++};if(t.dateMode!=='manual')next.due=target;
 if(Object.entries(next).some(([k,v])=>t[k]!==v))updates.push({id:t.id,before:{due:t.due||'',suggestedDate:t.suggestedDate||'',order:t.order??0},after:{...next,due:next.due??t.due??''}});
 }
 return {updates,warnings:[...new Set(warnings)]};}
 function period(mode,anchor,today,customStart,customEnd){const d=new Date(anchor+'T12:00:00Z'),y=d.getUTCFullYear(),m=d.getUTCMonth();let start,end,previous=null;if(mode==='quarter'){const q=Math.floor(m/3)*3;start=day(new Date(Date.UTC(y,q,1)));end=day(new Date(Date.UTC(y,q+3,0)));previous={start:day(new Date(Date.UTC(y,q-3,1))),end:day(new Date(Date.UTC(y,q,0)))}}else if(mode==='year'){start=y+'-01-01';end=y+'-12-31';previous={start:(y-1)+'-01-01',end:(y-1)+'-12-31'}}else if(mode==='custom'){start=customStart;end=customEnd}else{start='0001-01-01';end=today}return {start,end,previous,partial:end>today,future:start>today};}
 function summary(s,p){const inRange=d=>!!d&&d.slice(0,10)>=p.start&&d.slice(0,10)<=p.end;const events=s.events.filter(e=>inRange(e.date||e.time));const completions=new Set(events.filter(e=>e.type==='task_completed').map(e=>e.entityId));const milestones=new Set(events.filter(e=>e.type==='milestone_completed').map(e=>e.entityId));const delivered=new Set(events.filter(e=>e.type==='release_delivered').map(e=>e.entityId));const activities=s.careerActivities.filter(a=>inRange(a.date));const entries=s.entries.filter(e=>inRange(e.date));const income=entries.filter(e=>e.type==='Income').reduce((n,e)=>n+Math.round(Number(e.amount)*100),0)/100,expenses=entries.filter(e=>e.type==='Expense').reduce((n,e)=>n+Math.round(Number(e.amount)*100),0)/100;const categories={};activities.forEach(a=>categories[a.category]=(categories[a.category]||0)+1);return {completions:completions.size,milestones:milestones.size,delivered:delivered.size,activities,categories,income,expenses,assessments:s.history.filter(h=>inRange(h.time)),observations:s.observations.filter(o=>inRange(o.periodEnd)),events};}
 const api={day,shift,phases,migrate,seed,blocked,schedule,period,summary};if(typeof module!=='undefined')module.exports=api;else root.CareerEngine=api;
})(typeof window!=='undefined'?window:globalThis);
